-- Mois 4 (jours 91 à 120) du programme HABITUDES_DEFIS_30J_FR_V1, version 1 : remplace la reprise des 30 textes du mois 1.
-- Textes validés par Dr Justin Tshims le 27/10/2026 (« C'est bon pour les textes du mois 4 »). Généré depuis
-- editorial/habitudes-defis/mois-4-fr-relecture.md. Aucune inscription n'avait encore atteint le jour 91 : les textes
-- déjà servis (jours 1 à 90) ne changent pas. Activités, défis et horaires inchangés.
do $$begin
 if exists(select 1 from seneve.enrollments e where e.programme_id='HABITUDES_DEFIS_30J_FR_V1' and e.etat='active'
  and seneve.hd_date_du_jour(e.enrollment_id,91)<=(now()at time zone 'Africa/Kinshasa')::date)then
  raise exception 'Une inscription a déjà atteint le jour 91 : publier une nouvelle version plutôt que modifier celle-ci';
 end if;
 if (select count(*)from seneve.contents where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour between 91 and 120 and numero_message=1)<>30 then
  raise exception 'Jours 91 à 120 incomplets';
 end if;
end$$;
update seneve.contents set titre=$t$Un Dieu qui travaille$t$,principe=$t$Voir son travail honnête comme une manière de ressembler à Dieu.$t$,theme=$t$Quelle tâche ordinaire de ta journée veux-tu faire avec Dieu ?$t$,texte_officiel=$t$Le chapitre 3 s'ouvre sur une phrase courte : « Dieu ne fait pas pleuvoir des pains. Il bénit des mains. » Le livre rappelle aussi une parole de Jésus : « Mon Père agit jusqu'à présent ; moi aussi, j'agis » (Jean 5:17). Le Dieu de la Bible n'est pas un Dieu oisif. Quand tu travailles honnêtement, à la maison, aux champs, au bureau ou à l'école, tu Lui ressembles. Aujourd'hui, commence une tâche ordinaire en la confiant à Dieu.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 58 et 61.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=91 and numero_message=1;
update seneve.contents set titre=$t$Plus que survivre$t$,principe=$t$Retrouver le sens de son travail au-delà de la fatigue.$t$,theme=$t$Quelle partie de ton travail te pèse le plus en ce moment ?$t$,texte_officiel=$t$Le livre distingue le travail et sa peine. La chute n'a pas créé le travail ; elle y a ajouté « la sueur, la résistance, l'épine ». En Christ, dit-il, le travail retrouve sa dignité : « Tu ne travailles plus seulement pour survivre — tu travailles pour glorifier Dieu. » Ta fatigue est réelle, et elle compte pour Dieu. Aujourd'hui, nomme devant Lui la partie la plus pénible de ton travail, et demande-Lui la force de la faire avec sens.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, page imprimée 60.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=92 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : de l'alliance au travail$t$,principe=$t$Faire le point sur la semaine qui ouvre le quatrième mois.$t$,theme=$t$Quel moment de travail as-tu pu vivre avec Dieu cette semaine ?$t$,texte_officiel=$t$Cette semaine a fait le lien entre deux mois : la patience d'une alliance, tout ce qui t'est confié comme un prêt, le trésor qui attire le cœur, puis le travail, où Dieu bénit des mains. Relis tes déclarations sans te juger. Remarque un moment où tu as travaillé ou servi avec Dieu, même brièvement. Chaque mois qui commence est une occasion de reprendre simplement.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 55–57 ; chapitre 3, pages imprimées 58–61 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=93 and numero_message=1;
update seneve.contents set titre=$t$La petite porte$t$,principe=$t$Ne pas mépriser un travail modeste.$t$,theme=$t$Quelle petite porte as-tu peut-être mise de côté trop vite ?$t$,texte_officiel=$t$Le livre raconte l'histoire de Gaston, sans emploi depuis deux ans, qui refusait les postes « indignes de son niveau » en attendant « la grande porte ». Il a fini par accepter un travail de livreur, et l'a fait avec ponctualité et honnêteté. Le livre en tire une image : « la grande porte existait bel et bien. Elle était simplement cachée derrière la petite. » Si tu cherches ta place, regarde avec honnêteté les petites portes qui s'ouvrent déjà.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 61–64.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=94 and numero_message=1;
update seneve.contents set titre=$t$Encourager quelqu'un qui recommence$t$,principe=$t$Soutenir quelqu'un qui reprend courage.$t$,theme=$t$Qui a besoin d'un mot d'encouragement de ta part ?$t$,texte_officiel=$t$Le troisième jour de son nouveau travail, Gaston a été moqué par un ancien camarade et voulait tout arrêter. C'est sa femme qui l'a relevé : « Aujourd'hui, pour la première fois depuis deux ans, tu ressembles à un homme en marche. Ne t'arrête pas. » Une parole juste, au bon moment, peut aider quelqu'un à tenir. Pense à une personne qui recommence quelque chose de difficile, et dis-lui aujourd'hui une parole d'encouragement.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, page imprimée 63.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=95 and numero_message=1;
update seneve.contents set titre=$t$Sans fraude$t$,principe=$t$Être droit dans les petits détails du travail.$t$,theme=$t$Quel détail de ton travail aimerais-tu rendre plus juste ?$t$,texte_officiel=$t$De Jésus, l'Écriture dit : « dans la bouche duquel il ne s'est point trouvé de fraude » (1 Pierre 2:22). Le livre imagine le charpentier de Nazareth : pas de planche mal équarrie vendue comme droite, pas de parole gonflée. Il propose un tableau simple : en cas de retard, assumer et corriger ; en cas d'erreur dans un rapport, la signaler. Aujourd'hui, choisis un détail de ton travail à rendre plus juste : une heure, un chiffre, une promesse.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 64–67.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=96 and numero_message=1;
update seneve.contents set titre=$t$Avance en pleine eau$t$,principe=$t$Passer de l'attente à un pas concret.$t$,theme=$t$Quel premier pas concret repousses-tu depuis longtemps ?$t$,texte_officiel=$t$Pierre a pêché toute la nuit sans rien prendre. Jésus lui dit : « Avance en pleine eau, et jetez vos filets pour pêcher. » Le livre souligne que le Maître ne crée pas les poissons pendant que Pierre dort : « Il dit : avance. Jette. Agis. » Pierre devait ramer, jeter et tirer. Pense à un projet ou une démarche que tu repousses. Après l'avoir confié à Dieu, fais aujourd'hui un premier pas concret.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 67–68.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=97 and numero_message=1;
update seneve.contents set titre=$t$Plus que les poissons$t$,principe=$t$Se rappeler que le but n'est pas seulement le résultat.$t$,theme=$t$Qu'est-ce qui t'attire vers Dieu, au-delà de ce que tu reçois ?$t$,texte_officiel=$t$Devant les filets qui se rompent, Pierre ne compte pas les poissons. Il tombe aux genoux de Jésus. Puis l'Évangile dit : « Ils ramenèrent les barques à terre, laissèrent tout, et le suivirent » (Luc 5:11). Le livre conclut que le but de toute bénédiction professionnelle n'est pas de remplir tes filets, « mais te faire tomber amoureux de Celui qui les remplit ». Aujourd'hui, remercie Dieu pour Lui-même, pas seulement pour ce que tu reçois.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 68–69.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=98 and numero_message=1;
update seneve.contents set titre=$t$La foi et les mains$t$,principe=$t$Commencer avec ce que l'on a.$t$,theme=$t$Qu'as-tu déjà entre les mains pour commencer ?$t$,texte_officiel=$t$Le livre raconte l'histoire de Solange, veuve avec deux enfants, qui voulait vendre des beignets mais avait peur de commencer avec presque rien. L'auteur lui dit : « Commence avec ce que tu as. » Chaque matin, elle priait avant d'allumer le feu ; chaque soir, elle remerciait. Elle disait : « Je n'avais pas de capital. J'avais la foi et les mains. » Ce récit ne promet pas le même résultat à chacun. Il invite à regarder ce que tu as déjà entre les mains.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 69–70.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=99 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : la foi qui agit$t$,principe=$t$Faire le point sur la foi et l'action.$t$,theme=$t$Quel pas concret as-tu fait cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé de la petite porte, d'une parole qui relève, de l'honnêteté dans les détails, du premier pas qu'on repousse, de l'amour pour Celui qui remplit les filets et de la foi qui commence avec peu. Relis tes déclarations sans te comparer à personne. Remarque un pas concret que tu as fait, même modeste. Le livre le résume en quelques mots : « La foi et les mains. »$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 61–70 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=100 and numero_message=1;
update seneve.contents set titre=$t$Appelés au travail$t$,principe=$t$Être fidèle là où l'on est.$t$,theme=$t$Où Dieu te demande-t-il d'être fidèle en ce moment ?$t$,texte_officiel=$t$Le livre remarque que Dieu appelle souvent des gens en plein travail. Élisée labourait, Ruth glanait, David gardait les brebis, Pierre lavait ses filets. Il en tire une règle : « La fidélité dans l'ordinaire prépare la promotion dans l'extraordinaire — jamais l'inverse. » Ce n'est pas une promesse de promotion rapide ; c'est une invitation à la fidélité dans ton poste actuel. Aujourd'hui, fais ton travail ordinaire avec soin, parce qu'il compte.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 70–71.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=101 and numero_message=1;
update seneve.contents set titre=$t$Derrière ton comptoir$t$,principe=$t$Travailler comme pour le Seigneur.$t$,theme=$t$Quelle tâche ordinaire veux-tu faire de bon cœur aujourd'hui ?$t$,texte_officiel=$t$Paul écrit : « Tout ce que vous faites, faites-le de bon cœur, comme pour le Seigneur et non pour des hommes » (Colossiens 3:23). Le livre traduit : « c'est Christ que tu sers derrière ton comptoir, ta caisse, ton volant, ton clavier. » Cela vaut aussi pour les tâches de la maison et pour les études. Aujourd'hui, choisis une tâche que tu fais d'habitude sans y penser, et fais-la de bon cœur, pour le Seigneur.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, page imprimée 71.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=102 and numero_message=1;
update seneve.contents set titre=$t$Quelqu'un vérifie toujours$t$,principe=$t$Rester honnête même quand cela coûte.$t$,theme=$t$Où l'honnêteté te coûte-t-elle quelque chose en ce moment ?$t$,texte_officiel=$t$Le livre raconte l'histoire de Richard, comptable à Manille, que ses collègues trouvaient trop scrupuleux. Il répondait : « Quelqu'un vérifie toujours. Celui que je sers voit tout. » Une promotion lui a échappé au profit d'un collègue plus « souple ». Il a écrit sa démission, a prié, et l'a laissée dans le tiroir. Il a dit plus tard : « Ma fidélité m'a fait passer pour un perdant pendant deux ans. » Si l'honnêteté te coûte en ce moment, confie ce prix à Dieu.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 72–73.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=103 and numero_message=1;
update seneve.contents set titre=$t$L'enveloppe repoussée$t$,principe=$t$Refuser un gain malhonnête.$t$,theme=$t$Dans quelle situation ressens-tu parfois la pression d'arranger les choses ?$t$,texte_officiel=$t$L'auteur raconte qu'au temps de ses dettes, un homme lui a proposé une enveloppe pour signer un certificat arrangé. Il avoue qu'il n'a pas dit non tout de suite. Puis il a repoussé l'enveloppe : « Ce soir-là, je suis rentré avec mes dettes intactes — et ma conscience intacte. » Il ajoute : « cette nuit-là, j'ai dormi comme un homme riche. » Si une proposition douteuse se présente à toi, prends le temps de prier et de demander conseil avant de répondre.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 74–75.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=104 and numero_message=1;
update seneve.contents set titre=$t$Le Roi qui sert$t$,principe=$t$Accepter une tâche humble.$t$,theme=$t$Quelle tâche humble pourrais-tu faire aujourd'hui sans être vu ?$t$,texte_officiel=$t$Le chapitre 3 se termine en regardant Jésus. La veille de Sa mort, Il prend un linge et lave les pieds de Ses disciples, « le travail le plus bas de la maison » (Jean 13). Il dit : « Je suis au milieu de vous comme celui qui sert » (Luc 22:27). Le livre L'appelle « un Serviteur-Roi ». Aujourd'hui, fais une tâche humble que personne ne remarquera, en pensant à Lui.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, page imprimée 76.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=105 and numero_message=1;
update seneve.contents set titre=$t$Ce qui prend la place de Dieu$t$,principe=$t$Reconnaître ce en quoi l'on met sa confiance.$t$,theme=$t$Sur quoi t'appuies-tu en premier quand tu as peur ?$t$,texte_officiel=$t$Le livre précise que Mammon n'est pas seulement l'argent : « C'est tout ce qui cherche à prendre la place de Dieu dans ta confiance — un salaire, une relation, un diplôme, une position, une assurance. » Ces choses sont souvent bonnes. Le problème commence quand elles deviennent ce qui te rassure le plus. Aujourd'hui, demande-toi simplement sur quoi tu t'appuies quand tu as peur, et parle-en à Dieu.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 82–83.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=106 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : servir là où l'on est$t$,principe=$t$Faire le point sur la fidélité au travail.$t$,theme=$t$Quel petit geste de fidélité retiens-tu de cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé de la fidélité dans l'ordinaire, du travail fait de bon cœur, de l'honnêteté qui coûte, d'un gain refusé, du Roi qui sert et de ce qui peut prendre la place de Dieu. Relis tes déclarations sans te juger. Remarque une tâche faite avec plus de cœur, ou un moment d'honnêteté difficile. Ce sont souvent ces petits gestes qui forment le caractère.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 70–76 ; chapitre 4, pages imprimées 82–83 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=107 and numero_message=1;
update seneve.contents set titre=$t$Une lente substitution$t$,principe=$t$Remarquer ce qui a peu à peu remplacé la prière.$t$,theme=$t$Qu'est-ce qui a pris un peu de la place de ta prière ?$t$,texte_officiel=$t$Le livre raconte l'histoire de Serge, homme d'affaires croyant, qui priait moins à cause des réunions et lisait moins à cause des dossiers. Après une grave perte, il dit : « je ne sais même plus quand j'ai arrêté de vraiment prier. » Le livre décrit ce mouvement : « sans bruit, sans date, sans rupture visible. Juste une lente substitution. » Regarde aujourd'hui, sans t'accuser, ce qui a pu prendre peu à peu la place de ta prière.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 83–84.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=108 and numero_message=1;
update seneve.contents set titre=$t$« Je n'ai besoin de rien »$t$,principe=$t$Garder le besoin de Dieu dans les bons moments.$t$,theme=$t$Comment as-tu accueilli devant Dieu ta dernière bonne nouvelle ?$t$,texte_officiel=$t$L'Église de Laodicée disait : « Je suis riche, je me suis enrichi, et je n'ai besoin de rien » (Apocalypse 3:17). Le livre y voit un danger : l'abondance peut endormir le besoin de Dieu. Il propose une question simple : « mes bénédictions me rapprochent-elles de Dieu ou m'en éloignent-elles ? » Pense à une bonne chose reçue récemment. Laisse-la te conduire à la reconnaissance plutôt qu'à l'oubli.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 85–87.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=109 and numero_message=1;
update seneve.contents set titre=$t$Quand la cupidité s'habille en vertu$t$,principe=$t$Appeler les choses par leur nom, avec douceur.$t$,theme=$t$Ta prudence cache-t-elle parfois une peur ?$t$,texte_officiel=$t$Le livre observe que la cupidité ne se présente jamais sous son vrai nom : elle s'appelle « prudence », « prévoyance » ou « sens des affaires ». Paul, lui, parle de « la cupidité, qui est une idolâtrie » (Colossiens 3:5). Le livre propose un premier remède : la nommer devant Dieu. La prudence reste une vraie qualité ; la question est de savoir si elle cache parfois une peur ou un attachement. Prends un moment pour en parler à Dieu honnêtement.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 87–88.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=110 and numero_message=1;
update seneve.contents set titre=$t$Se réjouir du succès d'un autre$t$,principe=$t$Remplacer la comparaison par la joie.$t$,theme=$t$Pour quelle réussite d'une autre personne peux-tu te réjouir aujourd'hui ?$t$,texte_officiel=$t$Le livre décrit une réaction fréquente quand un autre réussit : chercher la faille, dire « il a dû tricher quelque part ». Il écrit que c'est souvent « de la convoitise qui porte une robe de juge ». Dans le tableau du chapitre, la réponse du Royaume au succès d'un frère est la joie sincère. Pense à une personne qui réussit autour de toi. Aujourd'hui, réjouis-toi pour elle, et si tu le peux, félicite-la.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 85 et 88.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=111 and numero_message=1;
update seneve.contents set titre=$t$Ne pas attendre d'avoir plus$t$,principe=$t$Laisser la générosité commencer maintenant, à sa mesure.$t$,theme=$t$Quel geste généreux est à ta portée aujourd'hui ?$t$,texte_officiel=$t$Le livre cite une phrase courante : « Je donnerai quand j'aurai plus. » Il répond que le montant n'est pas le problème, mais le cœur, et qu'un cœur fermé ne s'ouvre pas avec l'augmentation des revenus. La générosité peut donc commencer à la mesure de ce que tu as aujourd'hui : un peu d'argent si tu le peux, mais aussi du temps, un service, un repas partagé. Choisis un geste généreux à ta portée, sans te mettre en difficulté.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 88–89.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=112 and numero_message=1;
update seneve.contents set titre=$t$La joie de Zachée$t$,principe=$t$Laisser la présence de Jésus ouvrir les mains.$t$,theme=$t$Y a-t-il un tort que tu aimerais réparer ?$t$,texte_officiel=$t$Zachée, riche par des moyens douteux, reçoit Jésus chez lui. Sans que personne ne le lui demande, il dit : « Voici, Seigneur, je donne aux pauvres la moitié de mes biens, et si j'ai fait tort à quelqu'un, je lui rends le quadruple. » Jésus répond : « Aujourd'hui, le salut est entré dans cette maison. » Le livre note que la présence de Jésus a fait ce qu'aucune règle n'avait pu faire. Si tu as fait tort à quelqu'un, même un peu, pense à la manière de réparer.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, page imprimée 91.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=113 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : des mains qui s'ouvrent$t$,principe=$t$Faire le point sur l'argent et le cœur.$t$,theme=$t$Où tes mains se sont-elles un peu ouvertes cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé de ce qui remplace peu à peu la prière, du besoin de Dieu dans l'abondance, de la cupidité qui se déguise, de la joie pour le succès des autres, de la générosité à ta mesure et de la joie de Zachée. Relis tes déclarations sans te juger. Remarque si tes mains se sont un peu ouvertes, en argent, en temps ou en attention. Un seul pas suffit pour continuer.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 83–91 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=114 and numero_message=1;
update seneve.contents set titre=$t$Regarder ses dettes en face$t$,principe=$t$Faire un premier pas de courage avec ses dettes.$t$,theme=$t$Quelle dette, petite ou grande, aimerais-tu regarder en face ?$t$,texte_officiel=$t$Le livre cite Proverbes 22:7 : « celui qui emprunte est l'esclave de celui qui prête ». L'auteur, qui a lui-même porté des dettes, propose une première étape : « fais l'inventaire complet », noir sur blanc. Il reconnaît que cela fait mal : « on ne guérit pas une maladie qu'on refuse de diagnostiquer. » Si tu as des dettes, commence par les lister sur un papier qui reste à toi. SÉNEVÉ ne te demande ni tes montants ni tes créanciers.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 92–93.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=115 and numero_message=1;
update seneve.contents set titre=$t$Une victoire à la fois$t$,principe=$t$Avancer pas à pas vers la liberté.$t$,theme=$t$Quelle petite action réaliste peux-tu poser cette semaine ?$t$,texte_officiel=$t$Le livre décrit le chemin suivi par l'auteur pendant trois ans : réduire le superflu pour un temps, rembourser d'abord la plus petite dette pour créer de l'élan, et refuser toute nouvelle dette pour paraître. Il précise : « Ce n'est pas la seule méthode possible : c'est celle dont je peux témoigner. » Si une décision d'argent importante t'attend, demande aussi conseil à une personne compétente. Aujourd'hui, choisis une seule petite action réaliste.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 92–94.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=116 and numero_message=1;
update seneve.contents set titre=$t$Derrière les photos$t$,principe=$t$Se libérer du besoin de paraître.$t$,theme=$t$Quel rôle aimerais-tu arrêter de jouer ?$t$,texte_officiel=$t$Le livre décrit notre époque : « On souffre en silence derrière des photos de bonheur. » Il précise que le luxe n'est pas un péché, mais que le besoin de paraître peut devenir une prison. Il conclut : « La simplicité n'est pas la pauvreté. C'est la liberté de ne plus jouer un rôle. » Aujourd'hui, repère une dépense ou une habitude qui sert surtout à l'image que tu donnes, et demande-toi si tu veux la garder.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 94–96.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=117 and numero_message=1;
update seneve.contents set titre=$t$Le Roi aux mains ouvertes$t$,principe=$t$Regarder Jésus, qui s'est fait pauvre.$t$,theme=$t$Que t'inspire le choix de Jésus de se faire pauvre ?$t$,texte_officiel=$t$Paul écrit : « lui qui était riche, il s'est fait pauvre à cause de vous, afin que par sa pauvreté vous fussiez enrichis » (2 Corinthiens 8:9). Le livre rappelle Jésus né dans une mangeoire prêtée, sans lieu où reposer Sa tête. Il conclut que, lorsque Jésus demande d'ouvrir les mains, « Il ne te prend rien. Il t'apprend à Lui ressembler. » Prends un moment pour Le remercier de ce qu'Il a donné.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 96–97.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=118 and numero_message=1;
update seneve.contents set titre=$t$Remettre l'argent à sa place$t$,principe=$t$Faire de l'argent un serviteur.$t$,theme=$t$Quelle dépense veux-tu présenter à Dieu aujourd'hui ?$t$,texte_officiel=$t$Le chapitre 4 se termine ainsi : « L'argent est un excellent serviteur et un dieu misérable. » Sa prière demande : « Garde-moi de devenir esclave de mes propres bénédictions. » Aujourd'hui, avant une dépense, même petite, prends quelques secondes pour la présenter à Dieu. Ce geste simple rappelle qui est le Maître, et laisse l'argent à sa place : celle d'un outil.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 98–99.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=119 and numero_message=1;
update seneve.contents set titre=$t$Un atelier où le ciel touche la terre$t$,principe=$t$Faire un bilan paisible du mois et choisir un pas.$t$,theme=$t$Quel pas veux-tu garder pour le mois prochain ?$t$,texte_officiel=$t$Le chapitre 3 se termine par cette image : « quand un homme travaille avec Jésus, son atelier devient un lieu où le ciel touche la terre. » Ce mois a parlé du travail fait avec Dieu, de l'honnêteté, du service et de la place de l'argent dans le cœur. Relis tes bilans de semaine et choisis un seul pas pour le mois prochain. Ton bilan ne mesure ni ta foi ni ta valeur. Tes habitudes quotidiennes continuent, et tu peux adapter tes horaires à tout moment.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, page imprimée 78.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=120 and numero_message=1;
update seneve.programme_versions set valide_par=valide_par||' ; mois 4 (jours 91 à 120) validé le 27/10/2026'
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and valide_par not like '%mois 4%';
